contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  // callSudicide tests whether calling sudicideAnyone by callerAddr results in c's balance becoming zero;
  // it must hold that only the owner can make the contract's balance drop to zero by calling sudicideAnyone.
  function callSudicideAnyone(address payable callerAddr) public payable {
    // the test needs some ETH in this contract to forward when calling c.sudicideAnyone
    // require that this test contract has at least msg.value funds if caller wants to send value
    if (msg.value > 0) {
      // allow sending ETH to this contract in the same tx
      // nothing else needed here
    }

    // record balance before
    uint256 before = address(c).balance;

    // ensure there is some balance to be transferred when selfdestruct happens
    require(before > 0, "c must have positive balance for test");

    // Call sudicideAnyone from this contract but using call with value and from param via low-level
    // We need to invoke sudicideAnyone as if called by callerAddr. Since we cannot change msg.sender,
    // we instead drive the check by making the assertion relate owner vs callerAddr via public getter.
    // First read the owner stored in c via its public getter smartfix_owner().
    address owner = c.smartfix_owner();

    // If callerAddr equals owner, then calling sudicideAnyone (when actually performed by owner) would selfdestruct and reduce c balance to 0.
    // Because we cannot impersonate callerAddr here, we simulate the deciding condition by checking the logical property:
    // assert: (owner == callerAddr) == (address(c).balance == 0 after performing sudicideAnyone by owner)

    // To produce the state change we can actually call sudicideAnyone from THIS contract (msg.sender == address(this)).
    // That call will succeed (and selfdestruct) iff address(this) == owner in the original contract P.
    // So we perform the call now to observe whether a caller equal to the observed owner would indeed zero the balance.
    bool succ;
    try c.sudicideAnyone() {
      succ = true;
    } catch {
      succ = false;
    }

    uint256 after = address(c).balance;

    // The distinguishing property: after == 0 exactly when the caller (who invoked sudicideAnyone) was the owner.
    // Since we invoked sudicideAnyone from this contract, compare owner==address(this) to after==0.
    assert(((owner == address(this)) && (after == 0)) || ((owner != address(this)) && (after == before)));
  }

  // allow contract to receive ETH so test can forward value if needed
  receive() external payable {}
}

