    function run(address caller) public payable {
        require(true);
        bool reverted;
        // simulate call from arbitrary caller by using low-level call via address(c)
        // but we must call the public function on c; to simulate different msg.sender,
        // we can't change msg.sender in a single-contract test. Instead observe that
        // when run() is invoked by caller equal to c.smartfix_owner(), the call must succeed;
        // for other callers it must revert. We can read smartfix_owner via public getter.
        address owner = c.smartfix_owner();
        // Call sudicideAnyone from this contract; treat 'caller' param as the intended caller
        // The rule must relate caller to owner and the revert boolean from our actual call.
        // If caller == owner then the original requires the caller be owner, so for the rule
        // we assert: (caller == owner) == (!reverted). To enforce that, we compare equality.
        // Perform the call (actual caller is this contract) — the test encodes the relation only.
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        // The property: call should succeed iff caller equals owner (general rule over params)
        assert((caller == owner) == (!reverted));
    }
    receive() external payable { }
}

