pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed actor (an address) who will attempt to call sudicideAnyone
    function testFuzz_property(address caller, uint128 deposit) public {
        // keep deposit reasonable but wide
        deposit = uint128(bound(deposit, 0, type(uint128).max));

        // give some Ether to the contract so selfdestruct effect on balance is observable
        // fund the contract by sending from an external account
        address funder = address(0xABCD);
        vm.deal(funder, 1 ether);
        vm.prank(funder);
        // send deposit (bounded to 1 ether if zero deposit then still fine)
        uint256 toSend = deposit == 0 ? 1 wei : (uint256(deposit) % 1 ether);
        // ensure funder has enough
        if (toSend > 0) vm.deal(funder, toSend);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: toSend}('');
        require(sent);

        // Record pre-call contract balance
        uint256 beforeBalance = address(c).balance;

        // If fuzzed caller equals the owner (deployer), then calling should succeed on reference.
        // We want to test that only owner can make the contract destroyed in reference, but some non-owner
        // should be able to destroy in mutant. So try caller as fuzzed address.

        // Ensure caller has some Ether to pay gas (vm.prank uses EOA implicitly)
        vm.deal(caller, 1 wei);

        // Attempt the call as the fuzzed caller and capture whether the call succeeded (i.e., did not revert)
        bool ok;
        vm.prank(caller);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, read contract balance to see if it was destroyed (balance becomes 0 on selfdestruct)
        uint256 afterBalance = address(c).balance;

        // General property asserted: In the reference implementation, only the original deployer (owner)
        // can successfully destroy the contract; therefore for ANY caller not equal to the owner,
        // either the call reverts (ok == false) or the contract balance remains unchanged (afterBalance == beforeBalance).
        // This is equivalent to asserting that if the fuzzed caller is not the owner then the contract was not destroyed by them.

        // Derive owner address by reading the public smartfix_owner getter via the inheriting contract's storage.
        // The SmartFix sets owner to deployer (in setUp we used new C(), so owner == address(this) at deployment time of the test helper new C()).
        // Note: c was deployed in setUp by this test contract, so the owner is address(this). But the fuzzed caller is arbitrary.
        address owner = c.smartfix_owner();

        // The single required assertion (reads c's public surface: address(c).balance and getter).
        // If caller != owner then the contract should remain intact (afterBalance == beforeBalance).
        if (caller != owner) {
            assertTrue(afterBalance == beforeBalance);
        } else {
            // If caller == owner, reference allows destruction: either call succeeded and balance is 0, or call reverted unexpectedly.
            // We still assert a true condition to keep the single assert and ensure the property is universal for all inputs:
            // For owner, afterBalance is either 0 (destroyed) or unchanged; both are acceptable for reference, so assert true.
            assertTrue(true);
        }
    }
}

