contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  // single test entry: caller provides an address as 'who' and may fund this contract before calling.
  // We assert that if the caller is the owner, then calling sudicideAnyone does not make the caller receive the contract balance.
  function runTest(address payable who, uint256 fundAmount) public payable {
    // precondition: ensure this test contract has enough balance to send to C if needed
    require(address(this).balance >= fundAmount, "insufficient balance for funding");

    // If fundAmount > 0, fund the C contract by sending Ether directly to it.
    if (fundAmount > 0) {
      // transfer funds to C so there is some balance that could be selfdestructed to caller
      payable(address(c)).transfer(fundAmount);
    }

    // Observe owner via public getter smartfix_owner (inherited from SmartFix)
    address owner = c.smartfix_owner();

    // Call sudicideAnyone from this contract (msg.sender will be this contract)
    // We simulate the caller 'who' by requiring that 'who' equals address(this) or not; since we cannot change msg.sender,
    // we instead check the general property about owner vs caller: when the caller equals owner, the caller must not end up
    // as recipient of the contract balance. Here caller is address(this).
    // So we only perform the distinguishing action once: invoke sudicideAnyone.
    // This is the only state-changing call on c in this test.
    c.sudicideAnyone();

    // After the call, the distinguishing condition: if the caller was the owner, then address(this) must NOT have received
    // the former balance of c. We express that by comparing address(c).balance to 0 when caller==owner.
    // On the original P, only owner can call and selfdestructs to owner, but since our caller (this contract) is not the owner
    // (unless smartfix_owner == address(this)), the contract would have been self-destructed to owner and address(c).balance==0
    // However the critical distinguishing rule is: if caller==owner then address(c).balance != 0 should be false (i.e., balance==0)
    // For a simple general rule that P satisfies and M violates, we assert: if address(this) == owner then address(c).balance == 0
    assert(!(address(this) == owner) || address(c).balance == 0);
  }

  // allow receiving ETH so this contract can fund C
  receive() external payable {}
}

